// Звуки событий. Ничего не скачиваем: всё синтезируется прямо в браузере.
// Звук — это список голосов. Голос: { n: нота или частота, t: сдвиг, d: длина, v: громкость,
//   w: sine|square|triangle|sawtooth|noise, a: атака, s: доля длины на «удержание»,
//   g: во сколько раз уплывает высота (gd — за сколько секунд), vib: [частота, глубина],
//   h: обертоны [[кратность, громкость]], f: фильтр { t: тип, f: частота, to: куда уплывает, q } }.
let audio = null;
let master = null;
let noiseBuf = null;
let lastAt = 0;
let volume = 0.45;

// Громкость 0–100 из настроек; по умолчанию звуки тише, чем были.
export function setVolume(v) {
    volume = Math.max(0, Math.min(100, Number(v) || 0)) / 100;
    if (master) master.gain.value = volume;
}

// ---------- iPhone и iPad: звук даже в беззвучном режиме ----------
// Safari по умолчанию считает звуки страницы «фоновыми» (ambient): переключатель «Бесшумно» их глушит.
// Если сказать браузеру, что это «воспроизведение» (playback), звуки играют как музыка — без оглядки на переключатель.
// Новые iOS понимают navigator.audioSession; старым включаем тихую бесконечную дорожку <audio> — тогда Safari
// так же переводит страницу в режим воспроизведения. Минус обоих путей: музыка из другого приложения может встать на паузу.
const IS_IOS = typeof navigator !== 'undefined'
    && (/iP(hone|ad|od)/.test(navigator.userAgent || '') || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1));
let ignoreSilent = true;
let soundOn = () => true;
let silentEl = null;
let unlockBound = false;

export function isIOS() {
    return IS_IOS;
}

// on — играть ли в беззвучном режиме; enabled — включены ли звуки вообще (функция, читает настройки).
export function setSilentMode(on, enabled) {
    ignoreSilent = on !== false;
    if (typeof enabled === 'function') soundOn = enabled;
    if (!IS_IOS) return;
    applySession();
    if (!ignoreSilent || !soundOn()) stopSilentLoop();
    bindUnlock();
}

function applySession() {
    try {
        if (navigator.audioSession) navigator.audioSession.type = ignoreSilent && soundOn() ? 'playback' : 'auto';
    } catch { /* старый браузер — ничего */ }
}

// тишина в WAV: 0,5 секунды, 8 кГц, 8 бит — собирается прямо здесь, без файлов
function silentWav() {
    const n = 4000;
    const buf = new Uint8Array(44 + n);
    const dv = new DataView(buf.buffer);
    const str = (o, t) => { for (let i = 0; i < t.length; i++) buf[o + i] = t.charCodeAt(i); };
    str(0, 'RIFF'); dv.setUint32(4, 36 + n, true); str(8, 'WAVE'); str(12, 'fmt ');
    dv.setUint32(16, 16, true); dv.setUint16(20, 1, true); dv.setUint16(22, 1, true);
    dv.setUint32(24, 8000, true); dv.setUint32(28, 8000, true); dv.setUint16(32, 1, true); dv.setUint16(34, 8, true);
    str(36, 'data'); dv.setUint32(40, n, true);
    buf.fill(128, 44);
    let bin = '';
    for (let i = 0; i < buf.length; i++) bin += String.fromCharCode(buf[i]);
    return 'data:audio/wav;base64,' + btoa(bin);
}

function startSilentLoop() {
    if (navigator.audioSession) return; // новый Safari: хватает audioSession
    if (!silentEl) {
        silentEl = document.createElement('audio');
        silentEl.src = silentWav();
        silentEl.loop = true;
        silentEl.preload = 'auto';
        silentEl.setAttribute('playsinline', '');
        silentEl.setAttribute('x-webkit-airplay', 'deny');
        silentEl.disableRemotePlayback = true;
    }
    if (document.visibilityState === 'hidden') return;
    const p = silentEl.play();
    if (p && p.catch) p.catch(() => {});
}

function stopSilentLoop() {
    if (silentEl) silentEl.pause();
}

// Звук на iPhone можно включить только внутри касания — поэтому при первом же касании «будим» всё сразу.
function unlock() {
    if (!soundOn()) return;
    applySession();
    const ac = ctx();
    if (ac) {
        try {
            const src = ac.createBufferSource();
            src.buffer = ac.createBuffer(1, 1, 22050);
            src.connect(ac.destination);
            src.start(0);
        } catch { /* ничего */ }
    }
    if (ignoreSilent) startSilentLoop();
}

function bindUnlock() {
    if (unlockBound || typeof document === 'undefined') return;
    unlockBound = true;
    for (const ev of ['touchend', 'pointerup', 'click', 'keydown']) document.addEventListener(ev, unlock, { capture: true, passive: true });
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') stopSilentLoop();
        else if (audio && audio.state !== 'running') audio.resume().catch(() => {});
    });
}

function ctx() {
    if (!audio) {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return null;
        audio = new AC();
        // общий ограничитель: несколько звуков подряд не хрипят и не оглушают
        const comp = audio.createDynamicsCompressor();
        comp.threshold.value = -12;
        comp.knee.value = 6;
        comp.ratio.value = 4;
        comp.attack.value = 0.003;
        comp.release.value = 0.15;
        master = audio.createGain();
        master.gain.value = volume;
        master.connect(comp).connect(audio.destination);
        preloadSamples(audio);
    }
    if (audio.state === 'suspended' || audio.state === 'interrupted') audio.resume().catch(() => {});
    return audio;
}

function noise(ac) {
    if (!noiseBuf) {
        const len = ac.sampleRate * 2;
        noiseBuf = ac.createBuffer(1, len, ac.sampleRate);
        const data = noiseBuf.getChannelData(0);
        for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    }
    return noiseBuf;
}

// Настоящие записи (карандаш, перо, пенал) лежат рядом, в папке sounds. Грузятся один раз.
const sampleBufs = {};
const sampleLoading = {};
let sampleSource = name => new URL(`../sounds/${name}.mp3`, import.meta.url).href;

export function setSampleSource(fn) {
    sampleSource = fn;
}

function loadSample(ac, name) {
    if (sampleBufs[name]) return Promise.resolve(sampleBufs[name]);
    if (!sampleLoading[name]) {
        const src = sampleSource(name);
        const get = src instanceof ArrayBuffer ? Promise.resolve(src.slice(0)) : fetch(src).then(r => r.arrayBuffer());
        sampleLoading[name] = get
            .then(buf => new Promise((ok, fail) => ac.decodeAudioData(buf, ok, fail)))
            .then(buf => (sampleBufs[name] = buf))
            .catch(e => { console.warn('[Внутренний мир] запись не загрузилась', name, e); return null; });
    }
    return sampleLoading[name];
}

function preloadSamples(ac) {
    const names = new Set();
    for (const set of Object.values(PATTERNS)) for (const pat of Object.values(set)) for (const p of pat) if (p.smp) names.add(p.smp);
    for (const n of names) loadSample(ac, n);
}

function playBuffer(ac, dest, buf, at, v) {
    const src = ac.createBufferSource();
    const g = ac.createGain();
    src.buffer = buf;
    g.gain.value = v;
    src.connect(g).connect(dest);
    src.start(Math.max(at, ac.currentTime + 0.005));
}

const STEPS = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };

export function hz(n) {
    if (typeof n === 'number') return n;
    const m = /^([A-G])([#b]?)(-?\d)$/.exec(String(n || ''));
    if (!m) return 440;
    const k = STEPS[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0);
    const midi = (Number(m[3]) + 1) * 12 + k;
    return 440 * Math.pow(2, (midi - 69) / 12);
}

